<?php
declare(strict_types=1);
$enabled=[];$hasList=false;foreach($entryForm as $b){if(($b['type']??'')==='component'&&($b['enabled']??true))$enabled[]=(int)($b['component_id']??0);if(($b['type']??'')==='attendee_list'&&($b['enabled']??true))$hasList=true;}
$entryComponents=array_values(array_filter($entryComponents,static fn(array $c):bool=>in_array((int)$c['id'],$enabled,true)||($hasList&&($c['component_scope']??'booking')==='attendee')));
$tickets=array_values(array_filter($classOptions,static fn(array $r):bool=>!empty($r['value'])));
$perPerson=array_values(array_filter($entryComponents,static fn(array $c):bool=>($c['component_scope']??'booking')==='attendee'));
$perBooking=array_values(array_filter($entryComponents,static fn(array $c):bool=>($c['component_scope']??'booking')!=='attendee'));
$posted=(array)($_POST['attendees']??[]);if(!$posted)$posted=[['first_name'=>(string)($currentUser['first_name']??''),'last_name'=>(string)($currentUser['last_name']??''),'ticket'=>'','choices'=>[]]];

function attendee_selection(array $c,mixed $raw,array &$alerts,string $context):array{$ids=array_values(array_unique(array_filter(array_map('intval',is_array($raw)?$raw:[$raw]))));if(($c['input_kind']??'')==='choice_single')$ids=array_slice($ids,0,1);$options=[];foreach((array)($c['options']??[])as$o)$options[(int)$o['id']]=$o;$chosen=[];foreach($ids as$id)if(isset($options[$id]))$chosen[]=$options[$id];if(!empty($c['is_required'])&&!$chosen)$alerts[]=['type'=>'danger','message'=>'Choose '.($c['label_override']??$c['name']??'an option').' for '.$context.'.'];$value=array_map(static fn(array $o):array=>['id'=>(int)$o['id'],'label'=>(string)$o['label'],'note'=>(string)($o['note']??''),'price_adjustment'=>price_to_number($o['price_adjustment']??0)],$chosen);return['value'=>$value,'total'=>array_sum(array_column($value,'price_adjustment'))];}
function attendee_options(array $components,string $prefix,array $saved=[]):void{foreach($components as$c):?><fieldset class="mt-3"><legend class="fs-6 mb-1"><?php echo h((string)($c['label_override']??$c['name']));echo!empty($c['is_required'])?' *':'';?></legend><?php if(!empty($c['description'])):?><div class="choice-note mb-1"><?php echo strip_tags((string)$c['description']);?></div><?php endif;?><?php foreach((array)$c['options']as$o):$check=in_array((int)$o['id'],array_map('intval',(array)($saved[(int)$c['id']]??[])),true);?><label class="d-block"><input <?php echo($c['input_kind']??'')==='choice_single'?'type="radio"':'type="checkbox"';?> name="<?php echo h($prefix.'['.(int)$c['id'].']'.(($c['input_kind']??'')==='choice_single'?'':'[]'));?>" value="<?php echo(int)$o['id'];?>" data-adjustment="<?php echo h((string)price_to_number($o['price_adjustment']??0));?>" <?php echo$check?'checked':'';?>> <?php echo h((string)$o['label']);?><?php if((float)($o['price_adjustment']??0)!==0.0):?> (<?php echo h(format_price((float)$o['price_adjustment']));?>)<?php endif;?></label><?php endforeach;?></fieldset><?php endforeach;}
if(($_SERVER['REQUEST_METHOD']??'')==='POST'&&($_POST['action']??'')==='add_attendee_booking'){if(!$isLoggedIn){$_SESSION['flash_alerts']=[['type'=>'warning','message'=>'Please sign in to book this event.']];header('Location: '.$basePath.'/account');exit;}$email=trim((string)($_POST['contact_email']??''));$phone=trim((string)($_POST['contact_phone']??''));$clean=[];foreach($posted as$a){$f=trim((string)($a['first_name']??''));$l=trim((string)($a['last_name']??''));if($f!==''||$l!=='')$clean[]=['first_name'=>$f,'last_name'=>$l,'ticket'=>(string)($a['ticket']??''),'choices'=>(array)($a['choices']??[])];}if(empty($entriesAvailable))$alerts[]=['type'=>'danger','message'=>'Entries are not currently open for this event.'];if($email==='')$alerts[]=['type'=>'danger','message'=>'Provide a booking contact email.'];if(!$clean)$alerts[]=['type'=>'danger','message'=>'Add at least one attendee.'];$total=0.0;$booking=[];foreach($perBooking as$c){$s=attendee_selection($c,($_POST['booking_choices']??[])[(int)$c['id']]??[],$alerts,'this booking');if(!$s['value'])continue;$total+=$s['total'];$booking[]=['id'=>(int)$c['id'],'label'=>$c['label_override']??$c['name'],'input_kind'=>$c['input_kind'],'value'=>$s['value'],'line_total'=>round($s['total'],2)];}$map=[];foreach($tickets as$t)$map[(string)$t['value']]=$t;$people=[];foreach($clean as$a){if($a['first_name']===''||$a['last_name']===''){$alerts[]=['type'=>'danger','message'=>'Each attendee needs a first name and surname.'];continue;}$t=$map[$a['ticket']]??null;if(!$t){$alerts[]=['type'=>'danger','message'=>'Choose a ticket type for '.$a['first_name'].'.'];continue;}$line=price_to_number($t['price']??0);$components=[];foreach($perPerson as$c){$s=attendee_selection($c,$a['choices'][(int)$c['id']]??[],$alerts,$a['first_name']);if(!$s['value'])continue;$line+=$s['total'];$components[]=['id'=>(int)$c['id'],'label'=>$c['label_override']??$c['name'],'input_kind'=>$c['input_kind'],'value'=>$s['value'],'line_total'=>round($s['total'],2)];}$people[]=['first_name'=>$a['first_name'],'last_name'=>$a['last_name'],'name'=>$a['first_name'].' '.$a['last_name'],'ticket'=>['pricing_row_id'=>$t['pricing_row_id']??null,'label'=>$t['label'],'price'=>price_to_number($t['price']??0)],'components'=>$components,'total'=>round($line,2)];$total+=$line;}if(!$alerts){$meta=['contact_email'=>$email,'contact_phone'=>$phone?:null,'attendees'=>$people,'attendee_count'=>count($people),'components'=>$booking];$basket[]=['id'=>uniqid('bk',true),'event_id'=>$event['id'],'event_title'=>$event['title'],'price'=>round($total,2),'booking_type'=>strtolower((string)($event['event_type_name']??'event')),'booking_type_id'=>(int)($event['event_type_id']??0),'booking_type_label'=>(string)($event['event_type_name']??'Event'),'metadata'=>$meta];$_SESSION['basket']=$basket;$_SESSION['basket_last_added']=time();saveBasketForSession($pdo,session_id(),$basket,$currentUser['id']??null,$_SESSION['basket_last_added']);$_SESSION['flash_success']='Attendees added to your basket.';header('Location: '.$basePath.'/basket');exit;}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo h($event['title']);?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f7f8f1}.attendee-card{border:1px solid #d9e5d8;border-radius:12px;background:#fff}.choice-note{font-size:.85rem;color:#647064}.entry-total{background:#eef4ed;border-radius:14px;padding:1rem 1.5rem}</style><?php include __DIR__.'/views/header_styles.php';?></head><body><?php include __DIR__.'/views/header.php';?><main class="container py-5"><a class="btn btn-sm btn-outline-secondary mb-3" href="<?php echo h($basePath);?>/events">Back to Events</a><h1 class="h2"><?php echo h($event['title']);?></h1><?php include __DIR__.'/views/alerts.php';?><?php if(!$isLoggedIn):?><div class="alert alert-info">Please <a href="<?php echo h($basePath);?>/account">sign in</a> to book this event.</div><?php elseif(!$tickets):?><div class="alert alert-warning">No ticket types have been configured for this event.</div><?php else:?><form method="post" id="attendee-form"><input type="hidden" name="action" value="add_attendee_booking"><div class="card p-4 mb-3"><h2 class="h5">Booking contact</h2><div class="row g-3"><div class="col-md-6"><label class="form-label">Email</label><input required type="email" name="contact_email" class="form-control" value="<?php echo h((string)($_POST['contact_email']??($currentUser['email']??'')));?>"></div><div class="col-md-6"><label class="form-label">Phone</label><input name="contact_phone" class="form-control" value="<?php echo h((string)($_POST['contact_phone']??''));?>"></div></div><?php attendee_options($perBooking,'booking_choices',(array)($_POST['booking_choices']??[]));?></div><div id="attendees"><?php foreach($posted as$i=>$a):?><div class="attendee-card p-3 mb-3 attendee"><div class="d-flex justify-content-between"><h2 class="h5">Attendee <span class="attendee-number"><?php echo$i+1;?></span></h2><button type="button" class="btn btn-sm btn-outline-danger remove-attendee">Remove</button></div><?php include __DIR__.'/views/attendee_fields.php';?></div><?php endforeach;?></div><button type="button" id="add-attendee" class="btn btn-outline-success mb-3">Add another attendee</button><div class="entry-total d-flex justify-content-between align-items-center gap-3 flex-wrap"><strong class="fs-4">Total Entry Fee <span id="entry-total">£0.00</span></strong><button class="btn btn-success px-5">Add to basket</button></div></form><template id="attendee-template"><div class="attendee-card p-3 mb-3 attendee"><div class="d-flex justify-content-between"><h2 class="h5">Attendee <span class="attendee-number"></span></h2><button type="button" class="btn btn-sm btn-outline-danger remove-attendee">Remove</button></div><?php $i='__INDEX__';include __DIR__.'/views/attendee_fields.php';?></div></template><script>const box=document.getElementById('attendees'),tpl=document.getElementById('attendee-template'),form=document.getElementById('attendee-form');function renumber(){[...box.children].forEach((e,i)=>e.querySelector('.attendee-number').textContent=i+1)}function total(){let n=0;form.querySelectorAll('select[name*="[ticket]"]').forEach(s=>n+=Number(s.selectedOptions[0]?.dataset.price||0));form.querySelectorAll('input[data-adjustment]:checked').forEach(i=>n+=Number(i.dataset.adjustment||0));document.getElementById('entry-total').textContent='£'+n.toFixed(2)}document.getElementById('add-attendee').onclick=()=>{box.insertAdjacentHTML('beforeend',tpl.innerHTML.replaceAll('__INDEX__',box.children.length));renumber();total()};box.onclick=e=>{if(e.target.closest('.remove-attendee')&&box.children.length>1){e.target.closest('.attendee').remove();renumber();total()}};form.addEventListener('change',total);total()</script><?php endif;?></main></body></html>
